AutocompleteMatch ConvertScoredHistoryMatchToAutocompleteMatch(const ScoredHistoryMatch* history_match, int score) {
    AutocompleteMatch match;
    match.score = score;
    match.url = history_match->url;
    match.description = history_match->description;

    size_t url_length = strlen(history_match->url);
    size_t title_length = strlen(history_match->title);

    // Allocate memory for formatted URL and title
    match.formatted_url = (char*)malloc(url_length + 1);
    if (match.formatted_url) {
        strcpy(match.formatted_url, history_match->url);
    }

    match.formatted_title = (char*)malloc(title_length + 1);
    if (match.formatted_title) {
        strcpy(match.formatted_title, history_match->title);
    }

    // Set inline autocomplete offsets if applicable
    match.inline_autocomplete_offset = -1;
    if (history_match->inline_autocomplete_offset >= 0) {
        match.inline_autocomplete_offset = history_match->inline_autocomplete_offset;
    }

    // Format term matches for URL and title
    match.url_match_positions = FormatMatchPositions(history_match->url_match_positions);
    match.title_match_positions = FormatMatchPositions(history_match->title_match_positions);

    return match;
}

AutocompleteMatch ConvertScoredHistoryMatchToAutocompleteMatch(
    const ScoredHistoryMatch& history_match,
    int score) {
  AutocompleteMatch match;
  match.contents = history_match.url.spec();
  match.destination_url = history_match.url;
  match.description = history_match.title;
  match.relevance = score;
  match.transition =
      history_match.transition.type == PageTransition::TYPED ?
      PageTransition::TYPED : PageTransition::LINK;
  match.inline_autocompletion = std::string();
  match.has_history = true;

  size_t url_prefix_length = history_match.url_prefix_length;
  if (url_prefix_length > 0 && url_prefix_length < match.contents.size()) {
    match.contents_class.push_back(
        AutocompleteMatch::ACMatchClassification(0, 0));
    match.contents_class.push_back(
        AutocompleteMatch::ACMatchClassification(
            url_prefix_length, ACMatchClassification::URL));
    if (match.contents.size() > url_prefix_length)
      match.contents_class.push_back(
          AutocompleteMatch::ACMatchClassification(
              url_prefix_length, ACMatchClassification::URL));
  }

  size_t title_match_position = history_match.title_match_position;
  size_t title_match_length = history_match.title_match_length;
  if (title_match_position != std::string::npos &&
      title_match_length > 0) {
    if (title_match_position > 0)
      match.description_class.push_back(
          AutocompleteMatch::ACMatchClassification(0, 0));
    match.description_class.push_back(
        AutocompleteMatch::ACMatchClassification(
            title_match_position, ACMatchClassification::MATCH));
    if (title_match_position + title_match_length < match.description.size())
      match.description_class.push_back(
          AutocompleteMatch::ACMatchClassification(
              title_match_position + title_match_length, 0));
  }

  size_t url_match_position = history_match.url_match_position;
  size_t url_match_length = history_match.url_match_length;
  if (url_match_position != std::string::npos &&
      url_match_length > 0) {
    if (url_match_position > 0)
      match.contents_class.push_back(
          AutocompleteMatch::ACMatchClassification(0, 0));
    match.contents_class.push_back(
        AutocompleteMatch::ACMatchClassification(
            url_match_position, ACMatchClassification::MATCH));
    if (url_match_position + url_match_length < match.contents.size())
      match.contents_class.push_back(
          AutocompleteMatch::ACMatchClassification(
              url_match_position + url_match_length, 0));
  }

  return match;
}

AutocompleteMatch ConvertScoredHistoryMatchToAutocompleteMatch(
    const ScoredHistoryMatch* history_match,
    int score) {
  AutocompleteMatch match;
  match.fallback_match = false;
  match.is_history_match = true;
  match.relevance = score;

  // Retrieve the URL and title from the history match
  const GURL* url = &history_match->match()->url();
  match.contents = url->spec();
  match.contents_class = CreateTextFragmentSpan(match.contents.size());

  match.destination_url = *url;
  match.keyword = NULL;

  return match;
}

AutocompleteMatch ConvertScoredHistoryMatchToAutocompleteMatch(const ScoredHistoryMatch* history_match, int score) {
    AutocompleteMatch match;
    match.score = score;

    // Populate the URL and title
    snprintf(match.url, MAX_URL_LENGTH, "%s", history_match->url);
    snprintf(match.title, MAX_TITLE_LENGTH, "%s", history_match->title);

    // Format the description and display URL
    snprintf(match.description, MAX_DESCRIPTION_LENGTH, "%s", history_match->description);
    snprintf(match.display_url, MAX_DISPLAY_URL_LENGTH, "%s", history_match->display_url);

    // Handle inline autocomplete offsets if applicable
    match.inline_autocomplete_offset = -1;
    if (history_match->inline_offset >= 0) {
        match.inline_autocomplete_offset = history_match->inline_offset;
    }

    // Format term matches for URL and title
    FormatTermMatches(match.term_matches, history_match->term_matches, MAX_TERM_MATCHES);

    return match;
}

AutocompleteMatch ConvertScoredHistoryMatchToAutocompleteMatch(const ScoredHistoryMatch* history_match, int score) {
  AutocompleteMatch match;
  match.url = history_match->url;
  match.description = history_match->description;
  match.score = score;

  // Format the URL and description for display
  char url_buffer[256];
  snprintf(url_buffer, sizeof(url_buffer), "URL: %s", match.url);
  match.formatted_url = url_buffer;

  char description_buffer[256];
  snprintf(description_buffer, sizeof(description_buffer), "Description: %s", match.description);
  match.formatted_description = description_buffer;

  // Set inline autocomplete offsets if applicable
  match.inline_autocomplete_offset = -1;
  if (history_match->inline_match_offset > 0) {
    match.inline_autocomplete_offset = history_match->inline_match_offset;
  }

  // Handle formatting of term matches for URL and title
  match.url_match_positions = history_match->url_match_positions;
  match.title_match_positions = history_match->title_match_positions;

  return match;
}
